import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Projects","description":"","frontmatter":{},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md","lastUpdated":1785339549000}'),n={name:"projects/index.md"};function i(s,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><h2 id="🛡️-openshield-xdp" tabindex="-1">🛡️ OpenShield-XDP <a class="header-anchor" href="#🛡️-openshield-xdp" aria-label="Permalink to &quot;🛡️ OpenShield-XDP&quot;">​</a></h2><p>XDP-native DDoS mitigation at line rate. 16-stage detection pipeline with Bloom filter whitelist acceleration and freplace hot-patching.</p><p><a href="/pingless-studios-docs/openshield-xdp/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="⚡-bandwidth-manager" tabindex="-1">⚡ Bandwidth Manager <a class="header-anchor" href="#⚡-bandwidth-manager" aria-label="Permalink to &quot;⚡ Bandwidth Manager&quot;">​</a></h2><p>Production-grade Docker container bandwidth management. Per-container speed limits, daily traffic quotas, kernel-level tc enforcement with modern TUI and webhook notifications.</p><p><a href="/pingless-studios-docs/bandwidth-manager/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/Bandwidth-flow-maintainer" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🛡️-protection-plus" tabindex="-1">🛡️ Protection Plus <a class="header-anchor" href="#🛡️-protection-plus" aria-label="Permalink to &quot;🛡️ Protection Plus&quot;">​</a></h2><p>Host-level abuse protection and antivirus for hosting providers. Catches miners, outbound DDoS, Tor exits and proxies, port scans, webshells and malware uploads, zip bombs and exploits on Pterodactyl/Docker/VPS nodes — with per-container network visibility, on-access YARA + hash-blocklist scanning, Discord/email/webhook alerts, and automatic enforcement (kill, suspend, quarantine).</p><p><a href="/pingless-studios-docs/protection/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/protection" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="⚡-mcu-hitter" tabindex="-1">⚡ mcu-hitter <a class="header-anchor" href="#⚡-mcu-hitter" aria-label="Permalink to &quot;⚡ mcu-hitter&quot;">​</a></h2><p>High-performance DDoS testing and benchmarking tool. Supports UDP flood, TCP SYN, ICMP, raw packet crafting with IP spoofing.</p><p><a href="https://github.com/AnAverageBeing/mcu-hitter" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🗄️-s3-database-storage-for-vps" tabindex="-1">🗄️ S3 Database Storage for VPS <a class="header-anchor" href="#🗄️-s3-database-storage-for-vps" aria-label="Permalink to &quot;🗄️ S3 Database Storage for VPS&quot;">​</a></h2><p>Automatic PostgreSQL and MySQL/MariaDB backups to any S3-compatible storage. Interactive setup, auto-discovery, systemd scheduling, retention, off-site + on-node copies, Discord alerts, and an interactive extractor.</p><p><a href="/pingless-studios-docs/s3-database-storage-for-vps/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/s3-database-storage-for-vps" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="⚡-penetration-v3" tabindex="-1">⚡ Penetration-v3 <a class="header-anchor" href="#⚡-penetration-v3" aria-label="Permalink to &quot;⚡ Penetration-v3&quot;">​</a></h2><p>Advanced traffic generation and packet crafting tool for authorized penetration testing. Supports 38 methods across UDP, TCP, ICMP, HTTP/S, DNS, NTP, SNMP, application-layer protocols, and IPv6 with an interactive TUI wizard and scriptable CLI mode.</p><p><a href="/pingless-studios-docs/pentest-v3/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/Penetration-v3" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🎮-bandwidth-monitor-for-pterodactyl" tabindex="-1">🎮 Bandwidth Monitor for Pterodactyl <a class="header-anchor" href="#🎮-bandwidth-monitor-for-pterodactyl" aria-label="Permalink to &quot;🎮 Bandwidth Monitor for Pterodactyl&quot;">​</a></h2><p>Per-server network monitoring and bandwidth control for Pterodactyl panels. A Blueprint panel extension plus a Go agent on each Wings node: RX/TX speed caps via tc, day/week/month quotas per direction, throttle/suspend/log-only exceed actions, per-node pairing tokens, hourly/daily rollups, usage predictions, and reports in a native AdminLTE admin UI.</p><p><a href="/pingless-studios-docs/pterodactyl-bandwidth-monitor/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="glacier-theme-for-pterodactyl" tabindex="-1">Glacier Theme for Pterodactyl <a class="header-anchor" href="#glacier-theme-for-pterodactyl" aria-label="Permalink to &quot;Glacier Theme for Pterodactyl&quot;">​</a></h2><p>A calm, Apple-grade sidebar theme for Pterodactyl Panel, built on Blueprint. Replaces the stock top navigation with a customizable sidebar in three docks, reskins every page in dark and light mode with full per-mode palettes, and adds a console zones editor, dashboard cover-image cards, a visual tab manager, Ctrl+K search, 16 pure-CSS background patterns, announcements, and per-user privacy mode — all configured from a live-preview admin hub, with zero core-file replacement and zero external assets.</p><p><a href="/pingless-studios-docs/glacier/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="🛡️-liteshield-xdp" tabindex="-1">🛡️ LiteShield-XDP <a class="header-anchor" href="#🛡️-liteshield-xdp" aria-label="Permalink to &quot;🛡️ LiteShield-XDP&quot;">​</a></h2><p>Free, minimal XDP (eBPF) firewall for Linux 5.15+. One XDP program, one Go binary, one YAML config — per-source-IP rate limits, auto-ban, live whitelist/blacklist, built-in status TUI, and Discord webhook alerts. No license server, no daemons, MIT-licensed.</p><p><a href="/pingless-studios-docs/liteshield-xdp/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/LiteShield-XDP" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🚀-nitrocord" tabindex="-1">🚀 NitroCord <a class="header-anchor" href="#🚀-nitrocord" aria-label="Permalink to &quot;🚀 NitroCord&quot;">​</a></h2><p>Velocity-compatible Minecraft proxy with built-in, license-gated attack prevention — kernel ipset firewall, TCP fingerprinting, anti-bot verification, anti-VPN/GeoIP, packet flood scoring, null-ping-proof MOTD caching, exploit filters, and an attack-mode engine that adapts the whole proxy under load. Drop-in replacement for Velocity: all plugins work unchanged.</p><p><a href="/pingless-studios-docs/nitrocord/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="📦-more-projects" tabindex="-1">📦 More Projects <a class="header-anchor" href="#📦-more-projects" aria-label="Permalink to &quot;📦 More Projects&quot;">​</a></h2><p>Follow <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">PingLess Studios on GitHub</a> for new projects and updates.</p>',33)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
